async def act(page):
    """
    1) Use the site-aware search helper to locate the target post via the visible search widget.
    2) Navigate to the post URL returned by the helper.
    3) Fill the comment textbox with the requested text and attempt to submit.

    This implementation uses accessibility-role-centric selectors exclusively
    (page.get_by_role and .nth()). It calls the knowledge-base search helper
    create_curated_collection_by_search(...) as required.
    """

    # 1) Use the site-aware search helper to find the post by its (full) title.
    # This helper navigates to '/' internally and uses the complementary search widget.
    results = await create_curated_collection_by_search(
        page,
        "How to get rid of unwanted Christmas presents - without being found out",
        max_results=20,
        resolve_links=True,
    )

    # 2) Inspect returned results for a reasonable match.
    target = None
    for r in results:
        title = r.get("title", "")
        if title:
            # case-insensitive containment check
            if "how to get rid of unwanted christmas presents" in title.lower():
                target = r
                break

    # 3) Fallback searches (broader keywords) if exact title did not appear in results
    if not target:
        fallback_keywords = ["Christmas", "unwanted Christmas", "get rid of unwanted Christmas"]
        for kw in fallback_keywords:
            res = await create_curated_collection_by_search(page, kw, max_results=20, resolve_links=True)
            for r in res:
                title = r.get("title", "")
                if title and "how to get rid of unwanted christmas presents" in title.lower():
                    target = r
                    break
            if target:
                break

    if not target:
        # Could not find the post via search; nothing more to do.
        return

    post_url = target["url"]

    # 4) Navigate to the post page
    await page.goto(post_url)

    # 5) Fill the comment body. Try a strongly-named role first, then fall back to the first textbox.
    comment_text = "Interesting perspective."

    try:
        comment_box = page.get_by_role("textbox", name="Comment")
        if await comment_box.count() > 0:
            await comment_box.nth(0).fill(comment_text)
        else:
            any_textboxes = page.get_by_role("textbox")
            if await any_textboxes.count() > 0:
                await any_textboxes.nth(0).fill(comment_text)
    except Exception:
        # Defensive: try the first textbox if the named one fails
        try:
            any_textboxes = page.get_by_role("textbox")
            if await any_textboxes.count() > 0:
                await any_textboxes.nth(0).fill(comment_text)
        except Exception:
            pass

    # 6) Optionally fill name/email fields if present (common on WordPress comment forms)
    try:
        name_field = page.get_by_role("textbox", name="Name")
        if await name_field.count() > 0:
            await name_field.nth(0).fill("Commenter")
    except Exception:
        pass

    try:
        email_field = page.get_by_role("textbox", name="Email")
        if await email_field.count() > 0:
            await email_field.nth(0).fill("commenter@example.com")
    except Exception:
        pass

    # 7) Submit the comment. Try common accessible button names inside the page.
    submitted = False
    submit_names = ["Post Comment", "Submit Comment", "Submit", "Send", "Comment"]
    for name in submit_names:
        try:
            btn = page.get_by_role("button", name=name)
            if await btn.count() > 0:
                await btn.nth(0).click()
                submitted = True
                break
        except Exception:
            continue

    # 8) If no specifically-named submit button found, try to click the first button on the page.
    if not submitted:
        try:
            all_buttons = page.get_by_role("button")
            if await all_buttons.count() > 0:
                await all_buttons.nth(0).click()
                submitted = True
        except Exception:
            pass

    # 9) Wait briefly for any submission/confirmation to appear
    if submitted:
        try:
            await page.wait_for_timeout(2000)
        except Exception:
            pass

